from pathlib import Path
import json
p=Path(__file__).parent
for file,idx,lead in [
('experience',3,'Робот видел, как человек положил кружку в шкаф и закрыл дверцу. Просьба принести её поступила через час. Чтобы выполнить поручение, робот должен помнить, какую именно кружку он видел, где она была и что после этого произошло с дверцей. При наблюдении следующий запрос ещё неизвестен.'),
('personal',0,'У Анны рабочие встречи обычно дистанционные, а занятия с наставником проходят очно. У Бориса правило обратное. Оба пишут «назначь встречу на среду». Станет ли меньше ошибок в календаре, если при известном владельце правила агент явно выделит условие исключения? Проверить это стоит там, где цель встречи уже известна, доступна через инструмент или известна только пользователю.')]:
    f=p/(file+'.json');d=json.loads(f.read_text(encoding='utf-8-sig'));d[idx]['lead']=lead;f.write_text(json.dumps(d,ensure_ascii=False,indent=2),encoding='utf-8')

